<script lang="ts">
 import {onMount} from 'svelte';import * as api from '../../bindings';import ErrorNotice from '../../ErrorNotice.svelte';
 let resources=$state<api.ResourceView[]>([]),selected=$state('bge-model'),consent=$state(false),busy=$state(false),job=$state<api.ResourceJobView|null>(null),error=$state<api.CommandError|null>(null);let live=true,timer:ReturnType<typeof setTimeout>|undefined;
 let resource=$derived(resources.find(r=>r.id===selected));
 $effect(()=>{selected;consent=false;});
 onMount(()=>{void refresh();void api.resourceJobs().then(rows=>{if(!live)return;const current=rows.find(r=>r.status==='running');if(current){busy=true;void poll(current.operation_id);}}).catch(raw=>{if(live)error=api.asCommandError(raw);});return()=>{live=false;clearTimeout(timer);};});
 async function refresh(){try{const result=await api.resourceList();if(live)resources=result;}catch(raw){if(live)error=api.asCommandError(raw);}}
 async function install(mode:string){if(!consent||!resource||busy)return;busy=true;error=null;try{const id=await api.resourceInstall({version:1,resource_id:selected,mode,consent});if(live)await poll(id);}catch(raw){if(live){busy=false;error=api.asCommandError(raw);}}}
 async function poll(id:string){try{const result=await api.resourceStatus(id);if(!live)return;job=result;if(result.status==='running'){timer=setTimeout(()=>void poll(id),300);return;}busy=false;await refresh();}catch(raw){if(live){busy=false;error=api.asCommandError(raw);}}}
</script>
<details class="resources"><summary>Install or import local resources</summary><p>Optional resources stay outside cases and installers. A global installation can continue while a case closes. Models are never downloaded automatically.</p>
 <label>Reviewed resource<select bind:value={selected} disabled={busy}>{#each resources as item}<option value={item.id}>{item.file} · {(item.bytes/1024/1024).toFixed(1)} MiB{item.present?' · present':''}</option>{/each}</select></label>
 {#if resource}<dl><dt>Destination</dt><dd>{resource.destination}</dd><dt>Download</dt><dd>{resource.url}</dd><dt>License / integrity</dt><dd>{resource.license} · SHA-256 {resource.sha256}</dd></dl><p>{resource.present?'A file is present; integrity is checked before use.':'Missing resource. Import a file matching this exact identity, or explicitly download it.'}</p><label class="check"><input type="checkbox" bind:checked={consent} disabled={busy}/>I approve this size and destination. Download sends the resource URL and my network address to the hosting provider; import uses a native file picker.</label><div class="toolbar"><button type="button" disabled={!consent||busy} onclick={()=>install('import')}>Import reviewed file</button><button type="button" disabled={!consent||busy} onclick={()=>install('download')}>Download reviewed resource</button></div>{/if}
 {#if job}<p role="status">{job.status}: {job.stage} · {(job.transferred/1024/1024).toFixed(1)} / {(job.bytes/1024/1024).toFixed(1)} MiB</p>{#if job.status==='running'}<button type="button" onclick={()=>api.resourceCancel(job!.operation_id).catch(raw=>error=api.asCommandError(raw))}>Cancel resource operation</button>{/if}{#if job.error}<p role="alert">{job.error}</p>{/if}{/if}{#if error}<ErrorNotice {error}/>{/if}
</details>
<style>.resources{margin:24px 0;padding:20px;border:1px solid var(--border);border-radius:var(--radius-panel)}summary{cursor:pointer;font-weight:600}label{display:grid;gap:8px}.check{display:flex;align-items:start;line-height:1.6;margin:20px 0}dl{display:grid;grid-template-columns:140px minmax(0,1fr);gap:10px;font-size:12px}dd{margin:0;overflow-wrap:anywhere}p{color:var(--foreground-secondary);line-height:1.6;max-width:80ch}.toolbar{display:flex;gap:12px;flex-wrap:wrap}</style>
